export function useFish(): FishItem[] {
  const { language } = useLanguage();
  return useMemo(
    () =>
      FISH_RAW.map((r) => ({
    name: language === 'es' ? r.nameEs : language === 'pt' ? r.namePt : language === 'fr' ? r.nameFr : language === 'de' ? r.nameDe : r.nameEn,
    rarity: r.rarityEn,
    spot: r.spotEn,
    watertype: r.watertypeEn,
    time: language === 'es' ? localizeTime(r.timeEn, 'es') : language === 'pt' ? localizeTime(r.timeEn, 'pt') : language === 'fr' ? localizeTime(r.timeEn, 'fr') : language === 'de' ? localizeTime(r.timeEn, 'de') : language === 'en' ? r.timeEn : r.timeNl,
    weather: language === 'es' ? localizeWeather(r.weatherEn, 'es') : language === 'pt' ? localizeWeather(r.weatherEn, 'pt') : language === 'fr' ? localizeWeather(r.weatherEn, 'fr') : language === 'de' ? localizeWeather(r.weatherEn, 'de') : language === 'en' ? r.weatherEn : r.weatherNl,
    level: r.level,
    rarityColorKey: r.rarityColorKey,
    xp: r.xp,
    emoji: r.emoji,
    sellPriceByStar: r.sellPriceByStar,
      })),
    [language]
  );
}

/** Vissen gegroepeerd per event (huidig event + archief) — voor de "Events"-subtab op het Vissen-scherm. */
export function useFishEventGroups(): EventGroup[] {
  const { language } = useLanguage();
  const { payload } = useRemoteContent();
  return useMemo(
    () => buildSightingEventGroups('fish', payload?.event, payload?.pastEvents, language),
    [payload, language]
  );
}
